\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{booktabs}

\title{Yield Response in a Nine-Year Wheat--Soybean--Maize Rotation}
\author{G.~Okonkwo, L.~Ferreira, and H.~Bates}
\date{February 2026}

\begin{document}
\maketitle

\input{chapters/rotation}
\input{chapters/yields}

\end{document}

\section{Yield Results}
% ---- 2024 preliminary table (retired 2026-01-20); kept for comparison ----
% \begin{tabular}{lcc}
% \toprule
% Crop & Yield (t/ha) & s.e. \\
% \midrule
% Winter wheat & 4.02 & 0.09 \\
% Soybean & 2.61 & 0.14 \\
% Maize & 6.33 & 0.21 \\
% \bottomrule
% \end{tabular}
The 2025 harvest completed the rotation cycle; Table~\ref{tab:yields}
reports plot-level means for the final locked dataset.

\begin{table}[h]
\centering
\begin{tabular}{lcc}
\toprule
Crop & Yield (t/ha) & s.e. \\
\midrule
Winter wheat & 4.02 & 0.09 \\
Soybean & 2.84 & 0.11 \\
Maize & 6.58 & 0.19 \\
\bottomrule
\end{tabular}
\caption{Mean plot yields for the 2025 harvest.}
\label{tab:yields}
\end{table}

Differences among crops were consistent with the rotation-phase
expectations; no block effects were detected.

